        lines = [{**task, "closed": True} if task["id"] == "toy-0001" else task for task in published]
        lines.append({"id": "toy-0006", "title": "f0: half as many branches", "files": ["lib.c"], "goal": PROVED_GAIN, "parent": "toy-0001"})
