    def test_the_callers_job_must_carry_the_guard_and_a_guard_this_command_cannot_read_is_said(self):
        """The guard is the « if: » of the job that calls the run, never another job's: none is WRONG (the example and
        hosting.md give one); one written in a form this command does not read is CANNOT, with what it saw; and every
        caller has its line."""
        self.healthy()
        jobs = ("on:\n  workflow_dispatch:\njobs:\n  test:\n    if: github.ref == 'refs/heads/stable'\n    runs-on: ubuntu-latest\n"
                "    steps:\n      - run: echo\n  hive:\n{guard}    uses: \"Bee-ruche/hive/.github/workflows/run.yml@{ref}\"\n")
        for guard, word in (("    if: github.ref == 'refs/heads/stable'\n", "OK"), ("    if: \"github.ref == 'refs/heads/stable'\"\n", "OK"),
                            ("", "WRONG"), ("    if: ${{ github.ref == 'refs/heads/stable' }}\n", "CANNOT"),
                            ("    if: github.ref == 'refs/heads/stable' || true\n", "CANNOT"), ("    if: github.ref_name == 'stable'\n", "CANNOT")):
            with self.subTest(guard=guard):
                self.published_file(self.CALLER, jobs.format(guard=guard, ref=self.hive_commit))
                code, lines = self.doctor()
                self.assertEqual((code, self.word(lines, "caller")), (1 if word == "WRONG" else 0, word), lines)
                if word == "CANNOT":
                    self.assertIn(guard.strip(), self.text(lines, "caller"), "what it saw")
                if word == "WRONG":
                    self.assertIn("its job has no guard", self.text(lines, "caller"))
        self.published_file(".github/workflows/second.yml", self.caller())
        self.published_file(self.CALLER, self.caller())
        self.assertEqual([text.split(" ")[0] for word, text in self.said(self.doctor()[1], "caller")],
                         [".github/workflows/hive.yml", ".github/workflows/second.yml"], "each caller has its line")

    def test_the_hives_commit_is_looked_for_in_the_hives_own_clone_and_the_doctors_own_is_said(self):
        """OK when the hive's clone here holds the commit on its main; CANNOT when it is no clone, or does not show the
        commit on its main. The line says the commit the doctor itself runs at, and that the run uses the pinned one."""
        self.healthy()
        own = sh("git", "rev-parse", "HEAD", cwd=self.registry).stdout.strip()
        self.assertEqual(self.said(self.doctor()[1], "hive-commit"),
                         [("OK", f"{self.hive_commit}, a commit of the hive's main, 1 commit(s) behind it; the doctor runs at {own}, and the "
                                 "run uses the commit the project pins")])
        self.published_file(self.CALLER, self.caller(own))
        self.assertIn("the doctor runs at that same commit", self.text(self.doctor()[1], "hive-commit"))
        self.published_file(self.CALLER, self.caller(self.off_main))
        code, lines = self.doctor()
        self.assertEqual((code, self.word(lines, "hive-commit")), (0, "CANNOT"), lines)
        self.published_file(self.CALLER, self.caller("e" * 40))
        self.assertEqual(self.word(self.doctor()[1], "hive-commit"), "CANNOT")
        copy = Path(self.tmp.name) / "hive-copy"
        shutil.copytree(self.registry, copy, ignore=shutil.ignore_patterns(".git"))
        self.published_file(self.CALLER, self.caller())
        code, lines = self.doctor(registry=copy)
        self.assertEqual((code, self.word(lines, "hive-commit")), (0, "CANNOT"), lines)
        self.assertIn("not a clone", self.text(lines, "hive-commit"))

    def test_a_pin_that_lacks_what_mains_worker_tool_uses_is_a_note(self):
        """A pin on the hive's main whose run lacks what main's worker tool uses (the bees' signals, duties,
        publish-cut, the page's workflow): NOTE, which names each and says how far behind main the pin is, for the bees
        work with main's tool whatever the project pins (blackboxBee's pin, 95 commits behind, 27 November 2026). Each
        mark it looks for is one this tree holds. And a hive's tree another account owns is said so."""
        for name, path, mark in hive.PROTOCOL_FEATURES:
            self.assertIn(mark, (REGISTRY / path).read_text(encoding="utf-8"), name)
        self.healthy()
        self.published_file(self.CALLER, self.caller(self.old_pin))
        code, lines = self.doctor()
        self.assertEqual((code, self.word(lines, "hive-commit")), (0, "NOTE"), lines)
        text = self.text(lines, "hive-commit")
        self.assertIn("2 commit(s) behind it, lacks what main's worker tool uses: the bees' signals (Hive-Signal), duties (hive duty), "
                      "publish-cut, the page after each run (page.yml). ", text)
        self.assertEqual([name for name, _, _ in hive.PROTOCOL_FEATURES],
                         ["the bees' signals (Hive-Signal)", "duties (hive duty)", "publish-cut", "the page after each run (page.yml)"])
        self.assertNotIn("[cut]", text)
        self.published_file(self.CALLER, self.caller())
        with mock.patch.object(hive, "owned_elsewhere", side_effect=lambda place: Path(place) == Path(self.registry)), \
                mock.patch.object(hive, "git", side_effect=lambda repo, *args, **options: (
                    subprocess.CompletedProcess(args, 128, "", "") if Path(repo) == Path(self.registry) and args[:1] == ("rev-parse",)
                    else REAL_GIT(repo, *args, **options))):
            code, lines = self.doctor()
        self.assertEqual(self.said(lines, "hive-commit"), [("CANNOT", hive.OWNED_ELSEWHERE.format(
            what="the hive's own tree here", place=str(self.registry)))])

    def test_files_the_hive_made_executable_are_counted(self):
        """A backstop for the files an older worker's tool took as executable from its machine (blackboxBee's units,
        27 November 2026): the doctor counts the files the branch the hive writes holds as executable that the
        published branch holds as plain files or not at all, names none (the names are contributors'), and says how to
        list them."""
        self.healthy()
        self.assertFalse(self.said(self.doctor()[1], "modes"), "none: no line")

        def change(seed):
            for name in ("units/a.c", "units/b.c"):
                (seed / name).parent.mkdir(parents=True, exist_ok=True)
                (seed / name).write_text("int x;\n")
                os.chmod(seed / name, 0o755)
            os.chmod(seed / "lib.c", 0o755)  # (a file the published branch holds as a plain one)
        self.tip_change(change)
        code, lines = self.doctor()
        self.assertEqual((code, self.word(lines, "modes")), (0, "NOTE"), lines)
        text = self.text(lines, "modes")
        self.assertRegex(text, r"\A3 file\(s\) of \S+ executable that \S+ holds as plain files or not at all ")
        self.assertIn("| grep 'mode 100755'", text)
        self.assertNotIn("units/", text, "no name a contributor gave")
        self.assertNotIn("lib.c", text)

    def test_a_clone_another_account_owns_is_said_so(self):
        """git reads no repository another account owns (« detected dubious ownership »: a folder Docker Desktop shows
        a container), and a command of the hive's side then said something else (« transport 'file' not allowed »,
        « not a clone git can read »). The tool asks git first, and says what stops it, and how to go on."""
        dubious = b"fatal: detected dubious ownership in repository at '/repo'\nTo add an exception for this directory, call:\n"
        for code, stderr, owned in ((128, dubious, True), (128, b"fatal: not a git repository\n", False), (0, b"", False)):
            with self.subTest(stderr=stderr), mock.patch.object(hive, "git_raw", return_value=subprocess.CompletedProcess([], code, b".git\n", stderr)):
                self.assertIs(hive.owned_elsewhere("/repo"), owned)
        self.healthy()
        err = io.StringIO()
        with mock.patch.object(hive, "owned_elsewhere", return_value=True), mock.patch("sys.stdout", io.StringIO()), mock.patch("sys.stderr", err), \
                self.assertRaises(SystemExit) as ended:
            hive.main(["doctor", "--project", "Bee-ruche/toy", "--repo", str(self.clone()), "--registry", str(self.registry)])
        self.assertEqual(ended.exception.code, 2)
        self.assertRegex(err.getvalue(), r"\Ahive: --repo belongs to another account than this command's, and git reads no repository it "
                                         r"does not own [^\n]*\(cp -a\)[^\n]*another account's: /[^\n]*\n\Z")

